for f in $(grep -rl '"trigger"' packs/*/tasks/*/task.json); do echo "--- $f"; python3 -c "
import json,sys; d=json.load(open('$f')); print(' trigger=',d.get('trigger'),' pre=',d.get('preconditions'))
"; done

