// ON DEMAND ONLY, and asserted through the scheduler rather than off the field: the
// owner stopped the recurring prune because a capture deleted on the calendar is a
// loss nobody asked for, so what has to hold is that a tick NEVER mints an
// occurrence — the retention arithmetic runs when a person asks for it.
test('logs-prune: the schedule never asks it, whatever its other conditions say', async () => {
  const declared = (decl, id) => ({ pack: 'claudinite-growth', id, decl, taskPath: `packs/claudinite-growth/tasks/${id}` });
  const plan = await planSchedulerRun({
    tasks: [declared(logsPrune, 'logs-prune'), declared(dedup, 'growth-dedup')],
    items: [],
    now: AT,
    schedule: SCHEDULE,
    // The ask is the thing under test: a task the scheduler reaches for comes
    // through this seam, so logs-prune arriving here at all is the failure.
    evaluate: async (task) => {
      assert.notEqual(task.id, 'logs-prune', 'the scheduler asked a task that runs only on request');
      return { run: true, reason: 'fixture' };
    },
  });
  assert.deepEqual(plan.asked.map((a) => a.task), ['claudinite-growth/growth-dedup'],
    'the scheduled sibling is still asked — the fixture reaches job 1');
  assert.deepEqual(plan.ops.filter((o) => o.kind === 'create').map((o) => o.task), ['growth-dedup'],
    'and no standing item is filed for the prune');
});
EOF
